  Directory &directory() { return std::get<Directory>(value); }
  File &file() { return std::get<File>(value); }
  File_Clone &file_clone(Feather &fs) {
    auto &result = std::get<File_Clone>(value);
    if (result.cached_file_contents.empty()) {
